package com.jbrempresa.backend.entity;
import java.time.*;import com.fasterxml.jackson.annotation.JsonFormat;import jakarta.persistence.*;
@Entity @Table(name="representantes") public class Representante{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="rep_id") private Long repId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="per_id",nullable=false)private Long perId;@Column(name="rep_per_id",nullable=false)private Long repPerId;@Column(name="rep_tip",nullable=false,length=30)private String repTip;@Column(name="rep_fec_des")private LocalDate repFecDes;@Column(name="rep_fec_has")private LocalDate repFecHas;@Column(name="rep_pri",nullable=false)private Boolean repPri;@Column(name="rep_obs",length=500)private String repObs;@Column(name="rep_usu_mov",nullable=false,length=50)private String repUsuMov;@JsonFormat(pattern="dd/MM/yyyy HH:mm:ss")@Column(name="rep_fec_mov",nullable=false)private LocalDateTime repFecMov;@Column(name="rep_act",nullable=false)private Boolean repAct;
 public Long getRepId(){return repId;}public void setRepId(Long v){repId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getPerId(){return perId;}public void setPerId(Long v){perId=v;}public Long getRepPerId(){return repPerId;}public void setRepPerId(Long v){repPerId=v;}public String getRepTip(){return repTip;}public void setRepTip(String v){repTip=v;}public LocalDate getRepFecDes(){return repFecDes;}public void setRepFecDes(LocalDate v){repFecDes=v;}public LocalDate getRepFecHas(){return repFecHas;}public void setRepFecHas(LocalDate v){repFecHas=v;}public Boolean getRepPri(){return repPri;}public void setRepPri(Boolean v){repPri=v;}public String getRepObs(){return repObs;}public void setRepObs(String v){repObs=v;}public String getRepUsuMov(){return repUsuMov;}public void setRepUsuMov(String v){repUsuMov=v;}public LocalDateTime getRepFecMov(){return repFecMov;}public void setRepFecMov(LocalDateTime v){repFecMov=v;}public Boolean getRepAct(){return repAct;}public void setRepAct(Boolean v){repAct=v;}
}
